$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem
$dir=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../docs/review-20261101'))
$expected=Get-Content -LiteralPath (Join-Path $dir 'updated-tables.json') -Raw -Encoding UTF8|ConvertFrom-Json
$zip=[IO.Compression.ZipFile]::OpenRead((Join-Path $dir 'Tuan6_DacTaUC_CapNhat_20261101.docx'))
try{$reader=[IO.StreamReader]::new($zip.GetEntry('word/document.xml').Open());$d=[Xml.XmlDocument]::new();$d.LoadXml($reader.ReadToEnd());$reader.Dispose();$ns=[Xml.XmlNamespaceManager]::new($d.NameTable);$ns.AddNamespace('w','http://schemas.openxmlformats.org/wordprocessingml/2006/main');$tables=@($d.SelectNodes('//w:body/w:tbl',$ns));$count=0;foreach($table in $expected){foreach($cell in $table.cells){$p=$tables[$table.table].SelectNodes('w:tr',$ns)[$cell.row].SelectNodes('w:tc',$ns)[$cell.col].SelectNodes('.//w:p',$ns)[$cell.paragraph];$text=($p.SelectNodes('.//w:t',$ns)|ForEach-Object{$_.InnerText})-join '';if($text-cne $cell.text){throw ('Content mismatch '+$table.table+','+$cell.row+','+$cell.col+','+$cell.paragraph)};$count++}};@{tables=$tables.Count;paragraphsCompared=$count;wordMatchesSequenceSource=$true}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $dir 'WORD_SEQUENCE_TEXT_PROOF.json') -Encoding UTF8;Write-Output ('PASS: Word and sequence source match '+$count+' table paragraphs.')}finally{$zip.Dispose()}
